import * as fc from "fast-check"

describe("rrfFusion properties", () => {
  it("maintains all unique items", () => {
    fc.assert(
      fc.property(
        fc.array(fc.array(fc.record({ id: fc.string(), rank: fc.nat() }))),
        (lists) => {
          const fused = rrfFusion(lists)
          const uniqueIds = new Set(lists.flat().map(x => x.id))
          return fused.length === uniqueIds.size
        }
      )
    )
  })
})
