### Property-Based Tests
```typescript
it("items appearing in more lists have higher scores", () => {
  fc.assert(
    fc.property(fc.string(), (id) => {
      const list1 = [{ id, rank: 1 }]
      const list2 = [{ id, rank: 1 }]

      const single = rrfFusion([list1])
      const double = rrfFusion([list1, list2])

      const singleScore = single.find(x => x.id === id)?.rrfScore ?? 0
      const doubleScore = double.find(x => x.id === id)?.rrfScore ?? 0

      return doubleScore > singleScore
    })
  )
})
