### Test Layer Pattern
```typescript
// Track batch vs individual calls
let batchCalls = 0
let individualCalls = 0

const NomicNlpServiceTest = Layer.succeed(NomicNlpService, {
  embedBatch: (texts) => { batchCalls++; return Effect.succeed(texts.map(() => mockEmbedding)) },
  embed: (text) => { individualCalls++; return Effect.succeed(mockEmbedding) }
})
```

### Key Test Cases
1. `it.effect("batch embeds multiple texts efficiently")`
2. `it.effect("uses cache for hits, batches misses")`
3. `it.effect("maintains input order in output")`
4. `it.effect("handles partial cache hits")`

### Test Template
```typescript
it.effect("batches uncached texts", () =>
  Effect.gen(function*() {
    batchCalls = 0
    const svc = yield* EmbeddingService

    // Pre-cache one text
    yield* svc.embed("cached", "search_document")

    // Batch with one cached, two uncached
    const results = yield* svc.embedBatch(["cached", "new1", "new2"])

    expect(results.length).toBe(3)
    expect(batchCalls).toBe(1)  // Only one batch call for new items
  }).pipe(Effect.provide(TestLayers))
)`
